 need(fflush(positive)==0,"flush actual positive prefix before commit");TreeCommit c={};c.slot=slot;c.panel=panel;c.next_query=c.points=sum.points;c.occupied=sum.occupied;c.record_hash=hash;c.successful=successful;c.version=1;
